import{_ as i,o as e,c as l,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2019-06-19 :: Ceph Orchestration meeting","description":"","frontmatter":{"title":"2019-06-19 :: Ceph Orchestration meeting","date":"2019-06-19T00:00:00.000Z","updated":"2019-06-19T00:00:00.000Z","tags":["Ceph","Distributed Storage","Rook Toolkit","Orchestrator","CephFS","RBD","Ceph Orchestrator"],"categories":["会议纪要"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-06-19_-_-_Ceph_Orchestration_meeting.md","filePath":"posts/2019/2019-06-19_-_-_Ceph_Orchestration_meeting.md","lastUpdated":1780459816000}'),r={name:"posts/2019/2019-06-19_-_-_Ceph_Orchestration_meeting.md"};function s(n,t,a,p,_,h){return e(),l("div",null,[...t[0]||(t[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2019年6月19日</p><p><strong>参会人员</strong>： huh, me, paint him, Joshua, Brooke, Jim, Timm, Sebastian, Pierre, John Spray, Travis</p><p><strong>会议主题</strong>： 讨论Ceph分布式存储的Rook Toolkit服务接口、调度器（Orchestrator）功能以及后续行动计划。</p><p><strong>会议内容</strong>：</p><ol><li><p><strong>会议时间调整</strong>：</p><ul><li>由于新西兰的参会者时间较晚，会议决定将会议时间提前，以便所有参会者都能参加。</li><li>会议时间初步定于下午5:30。</li></ul></li><li><p><strong>安全守护者（Safe Demon）探讨</strong>：</p><ul><li>Joshua提出探讨安全守护者技术，这可能有助于所有调度器，特别是Essentia Orchestrator，以封装运行容器镜像所需的所有操作。</li><li>目前这一想法还处于概念阶段，没有代码实现。Rock Point方面有一个相关的pull request。</li></ul></li><li><p><strong>接口讨论</strong>：</p><ul><li>讨论了现有RTW服务接口存在的问题，包括不愉快的端点和RTW更新名称风格。</li><li>提出了改进接口的建议，例如提供新的端点以创建新的存储桶、配置新的存储桶组等。</li><li>讨论了将服务器管理、存储桶组管理和RDW结构管理分离的必要性。</li></ul></li><li><p><strong>RDW结构管理</strong>：</p><ul><li>讨论了RDW结构管理的最佳实践，包括使用Rook的admin命令进行管理，以便任何工具都可以轻松地进行此类管理。</li><li>强调了将RDW网关命令封装在调度器之外的重要性。</li></ul></li><li><p><strong>Rook与Ceph的集成</strong>：</p><ul><li>讨论了Rook与Ceph集成的细节，包括RDW网关和RDW实例之间的区别。</li><li>提出了将RDW网关视为默认区域，除非显式指定其他区域。</li></ul></li><li><p><strong>其他议题</strong>：</p><ul><li>Timm提到他在缓存库存和服务方面的工作进展，并已合并了Sebastian和Pierre的修改。</li><li>讨论了Ganesha的pull request以及与Dipsy编排相关的端点URL。</li></ul></li></ol><p><strong>行动计划</strong>：</p><ol><li>调整会议时间，确保所有参会者都能参加。</li><li>Joshua继续研究安全守护者技术。</li><li>改进RTW服务接口，包括提供新的端点和改进命令。</li><li>分离服务器管理、存储桶组管理和RDW结构管理。</li><li>进一步研究Rook与Ceph的集成细节。</li><li>Timm继续进行缓存库存和服务的工作，并合并相关pull request。</li></ol><p><strong>备注</strong>：</p><ul><li>会议中提到了一些关键术语，如RTW服务、调度器、RDW、Rook、Ceph等，这些术语在会议记录中已保留英文原文。</li></ul>',10)])])}const c=i(r,[["render",s]]);export{u as __pageData,c as default};
